fn inspect() {
    let artifact_root = std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../foreign");
    for relative in ["facet.json", "snapshot.rs"] {
        let facet = std::fs::read_to_string(artifact_root.join(relative)).unwrap_or_else(#[unknown] |error| panic!("{relative}: {error}"));
        assert_eq!(facet, relative, "{relative}");

    }
}

